//! Thinoda branding: the app logo (generated by `cargo xtask icons`) and tagline.

use crate::i18n::t;

/// Short product tagline shown next to the logo.
pub const TAGLINE: &str = "Give your thoughts shape.";
/// Public contact address shown in the About dialog.
pub const CONTACT_EMAIL: &str = "axelwolters@hotmail.com";
/// Public project home page.
pub const PROJECT_URL: &str = "https://github.com/AxelWol/Thinoda";

const LOGO_64: &[u8] = include_bytes!("../../../assets/icon-64.png");
const LOGO_256: &[u8] = include_bytes!("../../../assets/icon-256.png");

fn texture(ctx: &egui::Context, large: bool) -> Option<egui::TextureHandle> {
    let id = egui::Id::unique(("thinoda_logo", large));
    if let Some(tex) = ctx.data(|d| d.get_temp::<egui::TextureHandle>(id)) {
        return Some(tex);
    }
    let bytes = if large { LOGO_256 } else { LOGO_64 };
    let img = image::load_from_memory(bytes).ok()?.to_rgba8();
    let size = [img.width() as usize, img.height() as usize];
    let color = egui::ColorImage::from_rgba_unmultiplied(size, img.as_raw());
    let tex = ctx.load_texture("thinoda_logo", color, egui::TextureOptions::LINEAR);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

/// Tooltip and accessible name of the GitHub corner badge.
pub const GITHUB_BADGE_LABEL: &str = "Thinoda on GitHub";
/// Narrower status bars drop the badge so sheet tabs and status controls keep their room.
pub const GITHUB_BADGE_MIN_BAR_WIDTH: f32 = 480.0;

